import struct
import unittest

from task2_1_prototype.simulators.protocol_emulator import (
    MemoryMqttBroker, OpcUaNodeStore, SIGNALS, corrupt_frame, crc16, decode_plc_frame, encode_plc_frame)


class ProtocolTests(unittest.TestCase):
    def setUp(self):
        self.values = dict(zip(SIGNALS, (4200, 78.5, 4.8, .88)))
        self.frame = encode_plc_frame(1, self.values, 42)

    def test_plc_known_bytes_endian_crc_and_round_trip(self):
        # Independent fixed wire vector, not generated by the parser under test.
        self.assertEqual(self.frame.hex(), "aa5501030810681eaa01e0226001002adc46")
        self.assertEqual(len(self.frame), 18)
        self.assertEqual(crc16(b"123456789"), 0x4B37)
        self.assertEqual(decode_plc_frame(self.frame)["signals"], self.values)
        self.assertEqual(decode_plc_frame(self.frame.hex())["heartbeat"], 42)

    def test_signed_temperature_and_quantization(self):
        data = dict(zip(SIGNALS, (4200.49, -12.345, 1.235, .65435)))
        decoded = decode_plc_frame(encode_plc_frame(1, data, 65535, 2))
        self.assertEqual(decoded["signals"], dict(zip(SIGNALS, (4200, -12.35, 1.24, .6544))))
        self.assertEqual(decoded["control"], 2)

    def test_corrupt_frames_rejected_for_correct_reason(self):
        for kind, message in (("truncated", "length"), ("crc", "CRC"), ("unknown_address", "unknown device")):
            with self.subTest(kind=kind), self.assertRaisesRegex(ValueError, message):
                decode_plc_frame(corrupt_frame(self.frame, kind))
        for offset, value, message in ((0, 0, "header"), (4, 7, "length"), (3, 4, "function"), (13, 3, "control")):
            body = bytearray(self.frame[:-2])
            body[offset] = value
            packet = bytes(body) + struct.pack("<H", crc16(body))
            with self.assertRaisesRegex(ValueError, message):
                decode_plc_frame(packet)

    def test_invalid_encoder_inputs_and_extra_bytes(self):
        for field, value in (("load_ratio", 1.1), ("temperature_c", 400), ("vibration_mm_s", float("nan")),
                             ("spindle_speed_rpm", True)):
            with self.assertRaises(ValueError):
                encode_plc_frame(1, {**self.values, field: value}, 0)
        for address in (0, 248, True):
            with self.assertRaises(ValueError):
                encode_plc_frame(address, self.values, 0)
        with self.assertRaises(ValueError):
            decode_plc_frame(self.frame + b"\x00")

    def test_mqtt_actual_delivery_topic_filter_and_payload_isolation(self):
        broker = MemoryMqttBroker()
        a, b, c = broker.subscribe("mes/+/events"), broker.subscribe("mes/#"), broker.subscribe("factory/#")
        value = {"event": "released", "nested": {"quantity": 1}}
        broker.publish("mes/work_orders/events", value)
        value["nested"]["quantity"] = 99
        self.assertEqual(len(a), 1)
        self.assertEqual(len(b), 1)
        self.assertEqual(len(c), 0)
        a[0]["payload"]["nested"]["quantity"] = 88
        self.assertEqual(b[0]["payload"]["nested"]["quantity"], 1)

    def test_opcua_node_fields_and_read_copy(self):
        store = OpcUaNodeStore()
        stamp = "2026-10-28T02:30:00Z"
        store.write("ns=2;s=CNC_01.temperature_c", 78.5, stamp)
        node = store.read("ns=2;s=CNC_01.temperature_c")
        self.assertEqual(node, {"NodeId":"ns=2;s=CNC_01.temperature_c", "Value":78.5, "StatusCode":"Good", "SourceTimestamp":stamp})
        node["Value"] = 99
        self.assertEqual(store.read(node["NodeId"])["Value"], 78.5)
